begin;
do $$declare r record;begin
 if (select count(*) from _m030_recovery.control where state='SEALED')<>1 then raise exception 'm030_recovery_not_sealed';end if;
 for r in select row_data from _m030_recovery.program_rows loop insert into public.affiliate_program_master select * from jsonb_populate_record(null::public.affiliate_program_master,r.row_data) on conflict(id) do update set workspace_id=excluded.workspace_id,asp_name=excluded.asp_name,program_id=excluded.program_id,advertiser_name=excluded.advertiser_name,program_name=excluded.program_name,category=excluded.category,reward_type=excluded.reward_type,reward_summary=excluded.reward_summary,reward_details=excluded.reward_details,epc=excluded.epc,approval_rate=excluded.approval_rate,revisit_window_days=excluded.revisit_window_days,confirmation_days=excluded.confirmation_days,conversion_conditions=excluded.conversion_conditions,rejection_conditions=excluded.rejection_conditions,pr_points=excluded.pr_points,listing_policy=excluded.listing_policy,listing_ng_words=excluded.listing_ng_words,listing_ng_words_raw=excluded.listing_ng_words_raw,listing_ng_words_verification_status=excluded.listing_ng_words_verification_status,compliance_notes=excluded.compliance_notes,program_status=excluded.program_status,affiliate_url=excluded.affiliate_url,affiliate_link_status=excluded.affiliate_link_status,affiliate_url_updated_at=excluded.affiliate_url_updated_at,affiliate_url_updated_by=excluded.affiliate_url_updated_by,source_type=excluded.source_type,source_verified_at=excluded.source_verified_at,source_notes=excluded.source_notes,owner_notes=excluded.owner_notes,external_execution_allowed=excluded.external_execution_allowed,created_by=excluded.created_by,created_at=excluded.created_at,updated_at=excluded.updated_at,business_goal=excluded.business_goal,target_audience=excluded.target_audience,promotion_channels=excluded.promotion_channels,content_plan=excluded.content_plan,compliance_checklist=excluded.compliance_checklist,priority=excluded.priority,next_action=excluded.next_action,next_action_due_at=excluded.next_action_due_at,publication_status=excluded.publication_status,publication_url=excluded.publication_url,business_version=excluded.business_version;end loop;
 for r in select row_data from _m030_recovery.draft_rows loop insert into public.affiliate_program_drafts select * from jsonb_populate_record(null::public.affiliate_program_drafts,r.row_data) on conflict(program_master_id) do update set workspace_id=excluded.workspace_id,owner_user_id=excluded.owner_user_id,draft_payload=excluded.draft_payload,draft_version=excluded.draft_version,base_program_updated_at=excluded.base_program_updated_at,audit_metadata=excluded.audit_metadata,created_at=excluded.created_at,updated_at=excluded.updated_at;end loop;
end$$;
commit;
select jsonb_build_object('result','M030_PRE_APPLY_STATE_RESTORED','program_rows',(select count(*) from _m030_recovery.program_rows),'draft_rows',(select count(*) from _m030_recovery.draft_rows)) verification;
